{"tool":"execute","arguments":{"code":"vendors = {v['id']: v for v in data['vendors']}
skus = sorted(data['skus'])
choices = []
for s in skus:
    spec = data['skus'][s]
    choices.append([q for q in data['quotes'] if q['sku'] == s and spec['demand'] <= q['units'] <= spec['demand'] + 2 and q['arrival'] <= spec['deadline'] and q['quality'] == 'approved'])
feasible = []
for selected in itertools.product(*choices):
    by_sku = {q['sku']: q for q in selected}
    used = set(q['vendor'] for q in selected)
    if len(used) < 3 or sum(q['carbon'] for q in selected) > data['carbon_cap']:
        continue
    if any(q['needs_same_vendor_sku'] and by_sku[q['needs_same_vendor_sku']]['vendor'] != q['vendor'] for q in selected):
        continue
    total = 0
    valid = True
    for vid in used:
        v = vendors[vid]
        lots = [q for q in selected if q['vendor'] == vid]
        units = sum(q['units'] for q in lots)
        if units > v['unit_cap']:
            valid = False
            break
        gross = sum(q['units'] * q['unit_cents'] for q in lots)
        bps = v['tier_bps'] if units >= v['tier_units'] else 0
        merchandise = (gross * (10000 - bps) + 5000) // 10000
        cost = merchandise
        if gross < v['free_shipping_gross']:
            cost += v['shipping_cents']
        if len(set(q['sku'] for q in lots)) >= 2 and merchandise >= v['rebate_merchandise_min']:
            cost -= v['rebate_cents']
        total += cost
    if valid:
        feasible.append((total, [q['id'] for q in selected]))
print(sorted(feasible))
answer = min(x[0] for x in feasible)
print(FINAL(str(answer)))"}}

